def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if not color or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=y+dy,x+dx
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); stack.append(p)
            comps.append((color,cells))
    out=[[0]*w for _ in range(h)]
    for color,cells in comps:
        lo=min(y for y,x in cells); hi=max(y for y,x in cells)
        shift=-lo if lo+hi <= h-1 else h-1-hi
        for y,x in cells: out[y+shift][x]=color
    return out
